import React from 'react'
type Section={heading:string;text:string[]}
type Guide={title:string;sections:Section[]}
const guides:Record<string,Guide>={
'treasury-bill-calculator':{title:'Treasury Bills: Pricing, Yield, Taxes, Auctions, and Practical Return Analysis',sections:[
{heading:'How a T-Bill actually produces a return',text:['Treasury bills are short-term U.S. Treasury securities with maturities of one year or less. Unlike a conventional coupon bond, a bill generally pays no periodic coupon. An investor typically pays less than the amount received at maturity, and the difference is the interest earned. This discount structure is why purchase price, face value, days to maturity, and yield convention all matter when checking a calculator result.','For example, paying $9,850 for a bill that pays $10,000 at maturity creates $150 of nominal interest before federal tax. That $150 alone does not tell you the annualized yield because earning it over 4 weeks is very different from earning it over 52 weeks. A useful T-Bill calculator converts the holding-period return into comparable annual measures while keeping the actual dollar gain visible.']},
{heading:'Price, face value, and maturity value are different',text:['Face value, also called par or maturity value, is the amount Treasury pays when the bill matures. The purchase price is what the investor pays today. If a $10,000 face-value bill costs $9,760, the $240 difference is the gross interest if held to maturity. Investors should enter the actual price or investment amount consistently because confusing face value with cash invested will overstate or understate returns.','Bills purchased at auction may be quoted using an investment rate or high rate rather than a simple consumer APY. Secondary-market quotes can introduce bid-ask spreads and accrued market movements. When modeling a purchase, use the price you can actually transact at, not merely a headline yield, and remember that brokerage presentation can differ from TreasuryDirect terminology.']},
{heading:'Why bank discount yield can look lower',text:['The traditional bank discount yield uses the discount from face value, divides by face value rather than purchase price, and annualizes on a 360-day year. Those conventions make it unsuitable for a direct apples-to-apples comparison with many deposit APYs. It is a quotation convention, not the investor’s exact compound return on cash committed.','Suppose a bill with $10,000 face value costs $9,750 and matures in 182 days. The $250 discount can be expressed several ways. A bank-discount calculation starts with $250 divided by $10,000, while an investment-yield calculation relates earnings to the $9,750 actually invested. A calculator should label each result clearly so a user does not select the apparently largest number without understanding the convention.']},
{heading:'Use bond-equivalent yield for better comparisons',text:['Bond-equivalent yield, or BEY, adjusts a short-term discount security into a convention that is easier to compare with coupon-bearing fixed-income investments. It commonly uses the amount invested and a 365-day annualization framework. BEY is still not identical to APY because APY incorporates compounding assumptions, so the comparison horizon and reinvestment assumption should be explicit.','When choosing between a T-Bill, CD, money-market deposit, or high-yield savings account, compare yields on a consistent basis and then compare after-tax dollars. A five-percent number on two products may not mean the same thing if one is an APY and another is a simple annualized investment rate. The calculator is most useful when it translates the security into both dollar earnings and a comparable annual yield.']},
{heading:'State and local tax exemption can change the winner',text:['Interest on U.S. Treasury securities is generally subject to federal income tax but exempt from state and local income taxes. That feature can make a Treasury bill more attractive than a bank deposit with a slightly higher stated yield for an investor who pays meaningful state or local income tax. The benefit depends on the investor’s marginal rates and the tax treatment of the competing product.','A rough taxable-equivalent comparison can divide the Treasury yield by one minus the applicable state/local marginal rate when the alternative interest is fully taxable there, but real tax situations can be more complicated. Federal deductions, surtaxes, residency, and account type can affect the result. Use current tax rules and your actual marginal rates rather than assuming the highest published state rate applies to you.']},
{heading:'Auction purchases and competitive pricing',text:['Individual investors commonly submit noncompetitive bids at Treasury auctions, agreeing to accept the rate determined by the auction. This removes the need to predict the winning yield and is different from institutional competitive bidding. The eventual price can be above, below, or in unusual cases at par depending on the auction result and prevailing rates.','Because the final auction price is not known when a noncompetitive order is placed, a pre-auction calculator result is an estimate. After issuance, replace the assumed yield with the actual price and maturity details to calculate expected dollars accurately. Treasury auction calendars, issue dates, and settlement timing also matter when coordinating cash that is moving from another account.']},
{heading:'Secondary-market sale introduces price risk',text:['A T-Bill held to maturity has a known maturity payment backed by the U.S. government, but selling before maturity exposes the investor to market pricing. If market yields rise after purchase, the bill’s resale price can fall; if yields decline, the price can rise. Short maturities limit duration compared with long bonds, but they do not eliminate mark-to-market movement.','Therefore a calculator that assumes hold-to-maturity should not be used as a guaranteed resale-value estimator. If you might need the cash early, preserve a liquidity buffer and consider the brokerage spread or transaction mechanics. The maturity value is predictable; the price another investor will pay on an earlier date is not.']},
{heading:'Reinvestment risk matters in a T-Bill ladder',text:['A ladder spreads maturities across several dates so cash is returned periodically rather than all at once. The strategy can improve liquidity and reduce the need to guess the single best purchase date, but each maturing bill must be reinvested at whatever rates are available then. Falling rates can gradually reduce portfolio income even though existing bills mature as expected.','Model a ladder by separating each rung instead of multiplying one current yield across an entire year. A 4-week bill rolled repeatedly does not guarantee today’s annualized yield for twelve months. For planning, test a base case plus lower-rate and higher-rate reinvestment scenarios. This reveals how much of projected annual income depends on future auctions rather than securities already owned.']},
{heading:'Compare T-Bills with CDs and savings correctly',text:['Bank CDs may offer fixed rates for longer periods and can carry early-withdrawal penalties; savings accounts offer easier liquidity but variable rates; T-Bills have specific maturity dates and federal-only taxation of interest. Deposit insurance, Treasury backing, access, minimums, settlement, and tax treatment are separate considerations from headline yield.','Calculate the after-tax maturity proceeds for the exact amount and holding period you expect to use. Then consider convenience: automatic renewal, ability to sell, emergency access, and whether the account is tax-advantaged. A few basis points of yield may be less important than avoiding an early withdrawal or forced market sale when cash is needed.']},
{heading:'Inflation determines real purchasing-power return',text:['A positive nominal T-Bill return does not guarantee a positive real return. If inflation over the holding period exceeds the after-tax yield, the investor can finish with more dollars but less purchasing power. Short-term bills reset to market rates frequently, which can help when rates rise with inflation, but there is no contractual inflation adjustment like the mechanism associated with Treasury Inflation-Protected Securities.','For a planning estimate, compare expected after-tax annualized yield with an inflation assumption, but do not present the difference as certain. Inflation is only known after the fact. T-Bills are often used for capital preservation and near-term cash management, so the relevant question may be whether they improve return on money that cannot tolerate substantial market volatility.']},
{heading:'Day count and exact dates affect short-term returns',text:['With short maturities, a difference of several days can noticeably change annualized figures. Use actual issue, settlement, and maturity dates when available rather than assuming every month has 30 days. Quotation formulas may use 360 or 365 days depending on the metric, which is another reason two legitimate yield numbers can differ.','Do not manually round the purchase price too early. Treasury securities are priced with precision, and rounding both the discount and days can compound into a misleading annualized result. Keep full precision during calculation and round only the displayed dollars or percentage. For tax records, rely on official transaction statements rather than a rounded planning estimate.']},
{heading:'When the calculator result should not be treated as guaranteed',text:['The calculator can accurately apply a stated formula to the inputs, but it cannot guarantee a future auction rate, secondary-market execution price, reinvestment yield, inflation rate, or individual tax outcome. A projected annual income based on repeated reinvestment contains assumptions even when the first bill’s maturity proceeds are known.','Use the result as a decision model: verify the security’s CUSIP, maturity, quoted yield convention, price, and settlement details before purchase. For large cash balances, compare multiple maturities and liquidity needs instead of optimizing only for the highest displayed yield. The strongest T-Bill plan aligns maturity dates with when the money will actually be needed.']},
]},
'social-security-wep-calculator':{title:'Social Security WEP: Understanding the Formula, Pension Interaction, and Benefit Estimates',sections:[
{heading:'What WEP was designed to address',text:['The Windfall Elimination Provision historically changed the Social Security benefit formula for some workers who received a pension from employment not covered by Social Security while also qualifying for Social Security from covered work. It did not simply subtract a fixed pension percentage; it modified the formula used to calculate the primary insurance amount.','This topic changed materially with the Social Security Fairness Act, signed in January 2025, which repealed WEP and the Government Pension Offset for benefits payable after December 2023. A 2026 calculator or article must therefore distinguish historical WEP estimates from current-law benefit calculations and should not present the old reduction as an ongoing rule.']},
{heading:'Why current-law dates are essential',text:['Social Security rules are date-sensitive. Someone researching an older benefit statement, an appeal, or retroactive payment may encounter WEP terminology even though current prospective calculations no longer apply the provision. The correct answer depends on the benefit month being discussed, not just the worker’s retirement date.','For current planning, use the Social Security Administration’s latest benefit estimate and earnings record. For historical reconciliation, preserve the old calculation inputs and benefit months. A calculator can illustrate what WEP used to do, but it should prominently state that repeal changed payable benefits and that official SSA records control actual payments.']},
{heading:'How the regular Social Security formula starts',text:['Social Security retirement benefits begin with covered earnings that are wage-indexed and converted into average indexed monthly earnings, or AIME. A progressive formula then applies bend-point percentages to portions of AIME to calculate the primary insurance amount at full retirement age. Bend points are indexed by year of eligibility.','The historical WEP modification affected the percentage applied to the first segment of AIME for certain workers. Understanding this matters because WEP was a formula adjustment, not a tax on a government pension. Current-law estimates after repeal generally return to the regular formula, subject to all the other normal Social Security rules.']},
{heading:'Years of substantial covered earnings mattered historically',text:['Under the old WEP rules, the size of the first-factor adjustment could depend on the number of years with substantial earnings covered by Social Security. Workers with 30 or more qualifying years could avoid WEP, while the factor phased between 20 and 30 years. The dollar threshold for a substantial-earnings year changed over time.','Historical calculators therefore need year-by-year covered earnings rather than a simple count of years worked. A year in which earnings fell below the applicable threshold might not count even if Social Security tax was paid. For present planning this test is no longer used to impose WEP, but it can explain why an older SSA estimate differed from a newer one.']},
{heading:'Noncovered pensions are not all identical',text:['Public-sector and foreign pensions can arise from work where U.S. Social Security tax was not withheld, but pension structures differ. Defined-benefit plans, lump-sum distributions, mixed covered/noncovered careers, and foreign systems created special questions under historical WEP guidance.','Do not infer current Social Security treatment merely from the fact that a worker has a teacher, police, firefighter, civil-service, or foreign pension. Verify whether the employment was covered, which benefit months are involved, and how SSA classifies the pension. The repeal also means old rules found in archived articles can now mislead current retirees.']},
{heading:'WEP and GPO were different provisions',text:['WEP historically affected a worker’s own retirement or disability benefit calculation. The Government Pension Offset affected certain spouse or survivor benefits when the person receiving those benefits also had a noncovered government pension. The two rules were often discussed together but operated differently.','The Social Security Fairness Act repealed both, which is why households may see changes in more than one type of benefit. A calculator labeled WEP should not attempt to estimate spouse or survivor effects using the old WEP formula. Those benefits have their own eligibility, family maximum, claiming-age, and survivor rules.']},
{heading:'Claiming age still changes retirement benefits',text:['Repeal of WEP does not remove normal early- or delayed-claiming adjustments. Claiming retirement benefits before full retirement age generally reduces the monthly amount, while delaying beyond full retirement age can earn delayed retirement credits up to the applicable age limit.','Compare claiming strategies using the post-repeal primary insurance amount as the base. A higher current-law benefit can change break-even analyses, household cash flow, and survivor planning, but it does not automatically mean claiming immediately is best. Longevity, work plans, taxes, spouse benefits, and liquidity remain relevant.']},
{heading:'The earnings test is separate from WEP',text:['People who claim before full retirement age and continue working can be subject to the retirement earnings test when earnings exceed annual limits. Benefits withheld under that test are not the same as a WEP reduction, and the mechanics change once full retirement age is reached.','A retiree seeing a lower payment should identify the reason before assuming an old WEP calculation remains in force. Medicare premiums, tax withholding, overpayment recovery, the earnings test, and other deductions can affect the deposit amount. Compare the gross benefit on the SSA notice with the net bank deposit.']},
{heading:'Taxes on Social Security are another separate calculation',text:['Federal income taxation of Social Security depends on provisional income and filing status under tax rules, not on WEP. Some households may owe federal tax on a portion of benefits, while state treatment varies. A larger benefit after repeal can therefore have downstream tax effects.','When building a retirement budget, calculate gross Social Security first, then estimate taxes and Medicare-related deductions separately. Avoid applying a marginal tax rate directly to the entire benefit. For significant pension plus Social Security income, model the household return or consult a tax professional.']},
{heading:'Check your earnings record before trusting projections',text:['A Social Security estimate is only as good as the earnings history underlying it. Missing or incorrect covered wages can affect AIME and therefore the benefit. Workers with careers split between covered and noncovered systems should pay particular attention because gaps may be legitimate or may reflect reporting errors.','Create or review an official my Social Security account and compare annual earnings with W-2s, tax records, or other documentation. Correcting an earnings record can matter more than fine-tuning a calculator assumption. Keep records for years where the online history looks inconsistent.']},
{heading:'Retroactive adjustments after repeal',text:['Because repeal applies to benefits payable after December 2023, SSA had to adjust affected records and issue retroactive amounts for many beneficiaries. Timing, prior withholding, deceased beneficiaries, and other case details can make an individual payment history more complicated than multiplying an old WEP reduction by a number of months.','If reconciling a retroactive payment, use official notices showing the revised monthly benefit and effective dates. A public calculator can estimate magnitude but cannot see SSA’s complete record. Be cautious of anyone requesting payment or sensitive information to “unlock” a WEP refund; official Social Security adjustments do not require paying a private intermediary.']},
{heading:'Use historical WEP calculators for education, not current deductions',text:['An old-formula calculator remains useful for understanding why pre-repeal estimates were lower and for comparing historical statements. It can show the role of AIME, bend points, years of substantial earnings, and the historical maximum reduction.','For a 2026 retirement decision, however, the output should default to current law or clearly mark the WEP result as historical. Content that says a new retiree “will lose” a stated amount to WEP is outdated. Always verify current SSA guidance because legislation and annual benefit parameters can change.']},
{heading:'Build a complete retirement-income view',text:['Social Security is one stream alongside pensions, retirement accounts, taxable savings, employment income, and possibly spouse or survivor benefits. Repeal may improve expected cash flow for households with noncovered pensions, but it should be integrated into a full plan rather than treated as isolated windfall money.','Model income by year, including claiming dates, pension start dates, required distributions when applicable, taxes, Medicare premiums, and inflation. Use conservative longevity assumptions and keep official SSA estimates as the source of record. The calculator’s role is to explain scenarios, not replace an agency benefit determination.']},
]},
'wealth-calculator':{title:'Wealth Building: Net Worth, Compounding, Contributions, Inflation, and Scenario Planning',sections:[
{heading:'Start with net worth, not income alone',text:['Wealth is commonly measured as assets minus liabilities. A high salary can coexist with low or negative net worth when debt and spending are high, while a moderate-income household can accumulate substantial wealth through consistent saving and ownership of appreciating or income-producing assets.','List cash, investments, retirement accounts, property equity and other meaningful assets, then subtract mortgages, student loans, credit cards, personal loans and other debts. Use reasonable market values rather than purchase prices. The resulting snapshot is more useful when repeated periodically using the same definitions.',{heading:'Emergency reserves protect the compounding engine',text:['Long-term wealth plans can be derailed when every unexpected bill forces an investment sale or new high-interest debt. An emergency reserve creates a buffer between ordinary financial shocks and assets intended to compound for decades. The appropriate amount depends on job stability, household obligations, insurance deductibles, income variability, and access to other liquidity rather than one universal number of months.','Keep emergency money in an instrument suited to near-term access instead of assuming it should earn the same return as retirement assets. The reserve may reduce the projected portfolio balance slightly, but its purpose is risk control. Avoiding a forced sale during a market decline or avoiding expensive credit-card debt can preserve more long-term wealth than maximizing the expected return on every dollar.']},{heading:'Concentration can make a net-worth number fragile',text:['A founder, employee with company stock, or property owner can appear wealthy while most net worth depends on one business, security, industry, or local real-estate market. Concentrated assets can grow rapidly, but a single adverse event can affect income and wealth at the same time. A calculator using one average return does not capture this concentration risk.','Track what percentage of investable assets and total net worth depends on each major source. Diversification may involve taxes, vesting restrictions, transaction costs, control considerations, or emotional attachment, so it is not always an immediate all-or-nothing decision. The key is to recognize when a projected wealth target relies on one asset continuing to outperform without interruption.']},{heading:'Insurance protects wealth from catastrophic losses',text:['Building assets is only one side of a financial plan. Health, disability, property, liability, life, and business risks can create losses much larger than a normal monthly contribution. Appropriate insurance transfers selected catastrophic risks so that one event is less likely to erase years of accumulated capital or force the sale of long-term assets.','Insurance needs change as wealth, dependents, debts, employment benefits, and business ownership change. Do not subtract premiums from the plan and conclude that less insurance always accelerates wealth. The relevant comparison is the affordable recurring premium versus the financial impact of a loss the household cannot comfortably self-insure.']},]},
{heading:'Separate liquid wealth from total net worth',text:['A home, private business, or retirement account can add materially to net worth without providing immediate spending cash. Liquidity matters for emergencies, near-term goals, and the ability to avoid expensive borrowing. Two households with identical net worth can therefore have very different financial resilience.','Track a liquid-net-worth measure alongside total net worth by focusing on cash and assets that can be accessed with limited friction, while recognizing taxes and penalties where relevant. This does not make illiquid assets less valuable; it prevents a large headline number from hiding a shortage of usable reserves.']},
{heading:'Contribution rate often matters more than tiny return differences',text:['During the early accumulation years, the amount added each month can dominate portfolio growth. Increasing monthly investing from $500 to $800 may have a larger controllable effect than trying to select an investment that earns an extra fraction of a percent.','Use the calculator to test contribution increases separately from return assumptions. Link contributions to income growth or automate annual increases. This turns wealth building into a repeatable cash-flow process rather than a forecast that depends on consistently beating the market.']},
{heading:'Compounding needs time and reinvestment',text:['Compound growth means returns can themselves generate future returns. The effect becomes powerful over long horizons, but only if gains or income remain invested and fees, taxes, withdrawals, and losses do not consume the base. A smooth calculator curve is an illustration, not the path real markets follow.','Compare ten-, twenty-, and thirty-year horizons using the same contribution. The widening difference demonstrates the value of time. Also run a delayed-start scenario: postponing contributions can require much larger later deposits to reach the same target because lost compounding years cannot be purchased back cheaply.']},
{heading:'Nominal returns are not purchasing power',text:['A future balance of $1 million does not have today’s purchasing power if prices rise for decades. A wealth projection should either express future dollars nominally and inflate the goal, or convert growth into real terms after an inflation assumption. Mixing a nominal return with a goal stated in today’s dollars overstates progress.','If a portfolio is modeled at 7% nominal growth and long-run inflation is assumed at 2.5%, a rough real return is lower than 4.5% once compounding is treated correctly. Run both views. Nominal dollars help with account balances; real dollars help answer what the money may actually buy.']},
{heading:'Return assumptions should reflect asset mix',text:['Cash, bonds, diversified equities, real estate and private businesses have different expected returns, volatility, liquidity, and failure risks. Using one aggressive stock-market assumption for every asset can produce an unrealistic projection, especially when a large portion of wealth is held in cash or low-risk fixed income.','Estimate return by asset class or use a blended assumption consistent with the intended allocation. Then stress-test it. A plan that succeeds only at an optimistic return is fragile. A lower-return case can reveal the contribution increase or goal adjustment needed to create margin.']},
{heading:'Sequence of returns changes real-life outcomes',text:['A basic calculator often applies the same return every year. Actual markets vary. During accumulation, early declines can sometimes help new contributions buy assets at lower prices; near or during retirement, large early losses combined with withdrawals can be damaging because fewer assets remain to participate in recovery.','For long-term planning, do not interpret the smooth projection as a promise. Consider bad-start scenarios and maintain an asset allocation appropriate to the goal horizon. The closer the spending date, the more important it becomes to distinguish average return from the order in which returns arrive.']},
{heading:'Fees compound in the wrong direction',text:['Investment expense ratios, advisory fees, trading costs, account charges and fund-level expenses reduce the return that remains invested. A one-percentage-point annual drag can create a large dollar difference over several decades because the lost fees also lose future compounding.','Enter returns after expected recurring fees when possible. Compare products on total cost rather than one visible fee. Taxes can create an additional drag in taxable accounts, so account location and turnover may matter even when two investments have similar pre-tax performance.']},
{heading:'Debt payoff can be part of wealth building',text:['Every dollar of principal repaid reduces liabilities and therefore increases net worth, even though it does not appear as an investment balance. Paying down high-interest debt can provide a predictable financial benefit and improve cash flow once the obligation is eliminated.','Compare the debt interest rate, tax treatment, liquidity needs, employer retirement matches, and investment risk before deciding between extra debt payments and investing. High-cost revolving debt generally deserves different treatment from a low fixed-rate mortgage. The calculator should not assume all spare cash belongs in markets.']},
{heading:'Taxes and account type change usable wealth',text:['A $100,000 Roth account, $100,000 traditional retirement account, and $100,000 taxable brokerage account do not necessarily provide the same spendable amount because future taxes and withdrawal rules differ. Employer plans may also have matching contributions, vesting, or distribution restrictions.','For a simple net-worth statement it is reasonable to show account market values, but retirement-income planning should estimate after-tax resources. Avoid applying one tax rate to every account. Tax laws, basis, gains, deductions, and future income determine the actual result.']},
{heading:'Set milestones that are tied to goals',text:['Generic milestones such as a particular net-worth number by age can motivate some people but ignore income, family size, pensions, geography, health costs and personal goals. A better target connects assets to specific future obligations such as emergency reserves, home purchase, education, financial independence, or retirement spending.','Create separate time horizons and funding targets. Money needed in two years should not necessarily use the same risk assumptions as money needed in thirty years. When the calculator shows a shortfall, adjust one lever at a time—contribution, timeline, goal amount, or return assumption—to understand what is actually driving the result.']},
{heading:'Update the model instead of predicting perfectly',text:['A wealth calculator is most useful as a living plan. Salary changes, market returns, housing decisions, family needs, taxes, and interest rates will make a 30-year forecast wrong in detail. The objective is not perfect prediction; it is seeing whether current behavior is directionally consistent with the goal.','Recalculate after major life events and at a regular interval such as annually. Replace assumed starting balances with actual balances and preserve a conservative scenario. Progress measured against an updated plan is more actionable than comparing yourself with someone else’s net worth or a viral benchmark.']},
]},
'business-loan-calculator':{title:'Business Loans: Payment Structure, APR, Cash Flow, Fees, and Borrowing Decisions',sections:[
{heading:'Translate loan size into a cash-flow obligation',text:['A business loan is not affordable merely because a lender approves the principal. The operating question is whether recurring free cash flow can cover principal and interest while leaving enough money for payroll, taxes, inventory, maintenance, owner needs and unexpected slow periods.','Start with the proposed amount, rate and term to estimate payment, then place that payment inside a monthly cash-flow forecast. Use seasonal low months rather than only annual averages. A business with strong yearly profit can still face a liquidity problem when debt payments arrive before customer receipts.',{heading:'Covenants can restrict decisions before a payment is missed',text:['Commercial loan agreements may require minimum liquidity, leverage ratios, debt-service coverage, reporting, insurance, or limits on additional borrowing and distributions. A company can remain current on payments yet still breach a covenant, potentially triggering lender remedies or a requirement to obtain a waiver. These obligations are part of the financing cost even though they never appear in the monthly-payment formula.','Before accepting an offer, model covenant headroom under a downside case. Ask how often ratios are tested, which accounting definitions apply, and what reporting is required. A slightly more expensive facility with workable covenants can be safer than a low-rate loan whose restrictions conflict with the company’s normal seasonal swings, owner distributions, acquisition plans, or future capital needs.']},{heading:'Balloon payments require a separate exit plan',text:['Some loans amortize over a long schedule but mature earlier, leaving a balloon balance due at the end of the contractual term. The monthly payment can look attractively low because it is not designed to reduce the balance to zero by maturity. That structure creates refinancing or liquidity risk at a specific future date.','Calculate the expected balloon balance and identify how it will be paid: accumulated cash, asset sale, operating cash flow, or refinancing. Do not assume refinancing will automatically be available on similar terms. Credit conditions, collateral value, business performance, and interest rates can all be different when the balloon comes due.']},{heading:'Tax deductions do not make interest free',text:['Business interest may be deductible when it meets applicable tax requirements, but deductibility reduces taxable income rather than reimbursing the entire interest cost. Limitations, entity structure, use of proceeds, capitalization rules, and the business-interest limitation can affect timing or availability of a deduction.','Evaluate the loan first on pre-tax economics and cash flow, then incorporate a realistic tax effect with professional guidance when material. Borrowing one dollar to obtain a partial tax deduction is not a profit strategy. The project financed by the debt still needs to create sufficient economic value after interest, fees, operating costs, and risk.']},]},
{heading:'Amortizing loans split each payment',text:['With a standard amortizing term loan, each scheduled payment contains interest and principal. Early payments usually contain more interest because the outstanding balance is larger; later payments shift toward principal. The payment may stay constant while the composition changes.','Review an amortization schedule when evaluating refinancing or early payoff. The remaining balance after two years is not simply original principal minus two years of equal principal amounts. Knowing the balance also helps estimate collateral release, sale proceeds, and the cost of replacing the loan.']},
{heading:'APR and stated interest rate are not interchangeable',text:['The note rate determines interest under the contract, while APR is designed to reflect certain finance charges in a standardized annual measure. Origination fees and other charges can make the effective borrowing cost higher than the advertised rate. Business financing products do not always present costs as cleanly as consumer loans.','Compare actual dollars received with total required repayments and fees. If a lender deducts a fee from proceeds, a $100,000 loan may provide less than $100,000 of usable cash while payments are still based on the contractual amount. That difference should be included when comparing offers.']},
{heading:'Short terms reduce interest but raise payments',text:['Holding rate and principal constant, a shorter term generally produces a higher monthly payment but less total interest. A longer term lowers the scheduled payment and can improve near-term cash flow, but the business stays indebted longer and usually pays more interest.','Do not automatically choose the shortest term the spreadsheet can support in an average month. Preserve a cushion for revenue volatility. Conversely, extending a loan far beyond the useful life of the asset can leave the company making payments after the equipment or project has stopped producing value.']},
{heading:'Fixed and variable rates create different risks',text:['A fixed rate makes scheduled debt service easier to forecast. A variable rate can change with an index plus a spread, so payments or interest expense may rise when benchmark rates increase. Some facilities have floors, caps, reset periods, or interest-only structures that change the risk.','Stress-test variable debt at rates above the opening quote. If a two- or three-percentage-point increase would erase operating margin, the initial payment understates the financing risk. Read the note for the actual index, adjustment frequency, floor, cap and default-rate provisions.']},
{heading:'Debt service coverage ratio is a lender and owner metric',text:['Debt service coverage ratio compares cash available for debt service with required debt payments. Definitions vary by lender and transaction, but a ratio barely above 1.0 indicates little room for error. A higher cushion can make the business more resilient to sales declines or cost spikes.','Use the same income definition the lender uses when checking a covenant, and a conservative cash-flow definition for internal planning. EBITDA is not automatically cash available for debt because taxes, capital expenditures, working-capital needs and owner distributions can consume funds.']},
{heading:'Working-capital loans should match the cash cycle',text:['Borrowing to purchase inventory or bridge receivables can be sensible when the cash conversion cycle is predictable. The financing term should align with how quickly inventory sells and customers pay. Using long-term debt for recurring operating losses can hide a business-model problem rather than solve it.','Map when borrowed dollars leave the account and when the associated customer cash is expected to arrive. Include delayed collections, returns, bad debt and supplier terms. A line of credit may fit recurring short gaps better than a fully funded term loan, but fees and variable rates still need comparison.']},
{heading:'Equipment financing should be evaluated against asset economics',text:['For equipment, compare loan payment with the incremental revenue, labor savings, maintenance cost, downtime, tax effects and residual value created by the asset. A machine that saves $4,000 per month does not automatically justify a $3,500 payment if it also requires service contracts and additional staffing.','Match financing duration to realistic useful life. Consider whether technology may become obsolete before the loan matures and whether a down payment would preserve or strain liquidity. The calculator gives financing cost; the investment decision requires the equipment’s full cash-flow model.']},
{heading:'Prepayment rules can change the refinance decision',text:['Some business loans allow principal prepayment freely, while others include prepayment premiums, minimum interest, lockouts, or structures where the expected savings are smaller than borrowers assume. Refinancing also introduces new origination, legal, appraisal or closing costs.','When rates fall, compare remaining scheduled interest with the complete cost of the replacement loan and any payoff charge. Use the expected time you will keep the new debt, not its maximum contractual term, to judge break-even. Obtain an official payoff quote before relying on a calculator balance.']},
{heading:'Personal guarantees and collateral are economic costs',text:['Small-business borrowing can require a personal guarantee, business assets, real estate, receivables, inventory or other collateral. These provisions do not appear in a payment formula but materially change the owner’s downside risk. A lower interest rate is not necessarily the better offer if it requires unacceptable security.','Read lien and guarantee language with qualified advisers when the exposure is material. Understand what happens after default, whether the lender can pursue personal assets, and whether existing liens restrict future financing. Pricing should be considered together with covenants and security requirements.']},
{heading:'Compare SBA and conventional structures on total terms',text:['SBA-guaranteed loans can offer useful terms for eligible businesses, but program fees, guarantee rules, underwriting, collateral policies, use-of-proceeds restrictions and processing time can differ from conventional financing. Eligibility and current program parameters should be verified from official sources.','Do not assume “SBA loan” describes one uniform product. Compare the exact program and lender proposal with bank term loans, lines of credit, equipment financing and other appropriate sources. Focus on proceeds, payment, maturity, rate behavior, fees, prepayment terms and required guarantees.']},
{heading:'Borrow for a measurable return, not just available credit',text:['The strongest borrowing case connects debt to an activity expected to create cash flow or strategic value greater than its risk-adjusted financing cost. Examples include capacity with demonstrated demand, inventory with reliable turnover, or a project with contracted revenue. Borrowing because credit is available can weaken the balance sheet without improving earning power.','Build a base, downside and upside case before signing. In the downside case, reduce sales, delay customer payments and increase costs while keeping debt service intact. If the business remains viable, the loan has more resilience. If one modest miss causes a cash crisis, reduce the amount, extend the runway, or reconsider the investment.']},
]},
'freelancer-quarterly-tax-calculator':{title:'Freelancer Quarterly Taxes: Estimated Payments, Self-Employment Tax, Deductions, and Cash Planning',sections:[
{heading:'Quarterly payments are prepayments, not a separate tax',text:['Estimated tax payments are installments toward the federal income tax and other taxes expected on the annual return. Freelancers do not file four separate annual tax returns simply because they pay quarterly. The final return reconciles actual income, deductions, credits and payments, producing either tax due or an overpayment.','This distinction matters when income changes during the year. A calculator estimates what to reserve and send based on current assumptions; it does not lock in the final liability. Keep year-to-date bookkeeping current so later estimates can replace early guesses with actual profit.']},
{heading:'Tax is based on net business profit, not gross invoices',text:['Freelance revenue is only the starting point. Ordinary and necessary deductible business expenses can reduce Schedule C profit, subject to tax rules. Software, supplies, professional services, eligible advertising, business insurance and other costs may be deductible when properly substantiated.','Do not estimate taxes by applying a percentage to every client payment without considering legitimate expenses, but do not invent deductions to force profit lower. Maintain receipts and records, separate business and personal spending where practical, and categorize transactions consistently. The tax return depends on substantiated net profit.']},
{heading:'Self-employment tax is different from income tax',text:['Self-employed workers generally pay Social Security and Medicare taxes through self-employment tax because there is no employer withholding the employee portion from a paycheck and remitting an employer share. The calculation uses net earnings from self-employment and includes annual Social Security wage-base rules plus Medicare components.','Income tax is calculated separately using taxable income, filing status, deductions, credits and other household income. Adding a flat “30% freelancer tax” may be convenient for rough saving, but it is not the tax formula. A good calculator shows self-employment tax and estimated income tax as distinct layers.']},
{heading:'The Social Security wage base can matter with a W-2 job',text:['If a freelancer also earns W-2 wages, Social Security tax already paid through employment can affect how much additional Social Security portion is due through self-employment tax because the annual wage base applies across covered earnings. Medicare rules do not use the same cap.','Enter outside wages when the calculator supports them and reconcile with actual pay stubs. A side-business owner earning near or above the wage base can get a misleading estimate from a tool that assumes the freelance profit is the person’s only earned income.']},
{heading:'Additional Medicare Tax has its own thresholds',text:['Higher earned income can trigger Additional Medicare Tax under federal rules once applicable thresholds are exceeded. Filing status and combined wages/self-employment compensation matter, and employer withholding may not perfectly match the final household calculation.','Do not treat the ordinary Medicare component and Additional Medicare Tax as one universal percentage on all profit. For high-income households or spouses with wages, use a calculator that accepts the relevant income sources or verify the estimate with current IRS instructions.']},
{heading:'Safe-harbor rules can reduce underpayment-penalty risk',text:['Federal estimated-tax planning often uses safe-harbor concepts based on current-year tax or a percentage of prior-year tax, with special rules for higher-income taxpayers. Meeting a safe harbor can help avoid an estimated-tax underpayment penalty even if the final return still has a balance due.','This makes last year’s Form 1040 valuable. A freelancer with rapidly growing profit may choose payments based on the applicable prior-year safe harbor for penalty protection while separately reserving more cash for the expected final bill. Verify current thresholds and exceptions because the rules are specific.']},
{heading:'Due dates are usually quarterly but not evenly spaced',text:['Federal estimated-tax installments are commonly associated with four due dates during the year, but the periods are not four equal three-month quarters. Weekend and holiday rules can also move a deadline. State estimated-tax calendars may differ.','Use current IRS and state guidance rather than a repeating every-three-month reminder. Schedule payments several days early when moving money electronically and retain confirmation numbers. A missed payment is easier to document and correct when records show the intended amount and date.']},
{heading:'Uneven income may justify the annualized-income method',text:['Freelancers can have highly seasonal or lumpy income. Paying equal installments based on a strong late-year project may make earlier quarters look underpaid even though the income had not yet been earned. The annualized-income installment method can sometimes align required payments more closely with when income was received.','The method requires more detailed period-by-period records and tax calculations, so it is not simply “pay tax when each invoice arrives.” If income is very uneven and penalties are material, use the appropriate IRS form/instructions or professional help to calculate installments correctly.']},
{heading:'Home-office deductions require actual eligibility',text:['A qualifying home-office deduction can be valuable, but working from home does not automatically make every housing cost deductible. Federal rules generally require specific business use tests, and simplified and actual-expense methods can produce different results.','Measure and document the business area and understand how the space is used before including a deduction. Renters and homeowners can face different expense components, and depreciation under an actual-expense method can have later consequences. Do not let a calculator decide eligibility from square footage alone.']},
{heading:'Retirement contributions can change both savings and taxes',text:['Self-employed people may have access to retirement arrangements such as SEP IRAs, solo 401(k)s, or other plans depending on the business and employees. Contribution limits, deadlines, compensation definitions and employer/employee components vary by plan and tax year.','A contribution can reduce taxable income in some circumstances while moving cash into long-term savings, but it does not necessarily reduce every component of tax in the same way. Confirm plan rules before using a desired contribution as a deduction in an estimated-tax calculation.']},
{heading:'State and local obligations need a separate reserve',text:['Federal estimates are only part of the picture. Depending on location and business activity, a freelancer may face state income tax, local tax, sales tax, gross-receipts tax, business registration fees, franchise taxes or other obligations. Sales tax collected from customers is generally not business spending money.','Create separate reserve buckets when obligations are significant. A federal calculator should not imply its result is the complete tax bill. Check the official agencies for every jurisdiction where the business has filing or collection responsibilities, especially after moving or serving customers across state lines.']},
{heading:'Create a tax-reserve system around cash received',text:['A practical workflow is to move a chosen percentage of each client payment into a dedicated tax savings account, then update the percentage after each quarterly projection. This reduces the risk of spending money that will later be needed for tax while still allowing the reserve to respond to deductions and changing income.','The reserve percentage is a cash-management rule, not the tax rate. Keep enough liquidity for the upcoming payment even when invoices are late. If a client pays a large project near a deadline, update the year-to-date estimate before transferring the remaining cash to personal spending or long-term investments.']},
{heading:'Reconcile the calculator to real forms and records',text:['At year end, Forms 1099, payment-processor reports and client records may not perfectly equal bookkeeping revenue because of timing, reimbursements, duplicates or reporting rules. The taxpayer is responsible for reporting correctly rather than simply copying one information form total.','Reconcile bank deposits, invoices, bookkeeping and information returns before filing. Estimated payments should also be matched to IRS and state payment histories. The calculator is a planning layer; accurate books and official tax records are what allow the annual return to explain the numbers if questions arise.']},
]},
}
export function CalculatorBatch4DeepDive({slug}:{slug:string}){const g=guides[slug];if(!g)return null;return <article className="mt-8 rounded-2xl border border-gray-100 bg-white p-5 sm:p-7 text-gray-700"><h2 className="text-2xl font-black text-gray-900 mb-6">{g.title}</h2><div className="space-y-8">{g.sections.map(s=><section key={s.heading}><h3 className="text-lg font-bold text-gray-900 mb-3">{s.heading}</h3><div className="space-y-3">{s.text.map((x,i)=><p key={i} className="text-sm sm:text-base leading-7">{x}</p>)}</div></section>)}</div></article>}
